package com.example.catalog.product;

import java.util.List;
import org.springframework.data.domain.PageRequest;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class ProductService {

    private final ProductRepository repository;

    public ProductService(ProductRepository repository) {
        this.repository = repository;
    }

    // Read-only transactions skip dirty checking and can hit a replica
    @Transactional(readOnly = true)
    public List<ProductResponse> list(int page, int size) {
        return repository.findAll(PageRequest.of(page, size))
                .map(ProductResponse::from)
                .getContent();
    }

    @Transactional(readOnly = true)
    public List<ProductResponse> search(String term, int limit) {
        return repository.findByNameContainingIgnoreCase(term).stream()
                .limit(limit)
                .map(ProductResponse::from)
                .toList();
    }

    @Transactional(readOnly = true)
    public ProductResponse get(long id) {
        return repository.findById(id)
                .map(ProductResponse::from)
                .orElseThrow(() -> new ProductNotFoundException(id));
    }

    @Transactional
    public ProductResponse create(ProductRequest request) {
        Product product = new Product(request.name(), request.priceCents(), request.stock());
        return ProductResponse.from(repository.save(product));
    }

    @Transactional
    public void delete(long id) {
        if (!repository.existsById(id)) {
            throw new ProductNotFoundException(id);
        }
        repository.deleteById(id);
    }
}

package com.example.catalog.product;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;

@Service
public class StockService {

    private final ProductRepository repository;
    private final AuditService audit;

    public StockService(ProductRepository repository, AuditService audit) {
        this.repository = repository;
        this.audit = audit;
    }

    // The stock update and the audit row commit or roll back together
    @Transactional
    public void reserve(long productId, int quantity) {
        Product product = repository.findById(productId)
                .orElseThrow(() -> new ProductNotFoundException(productId));

        product.reserve(quantity);
        audit.record("reserved " + quantity + " of product " + productId);
    }

    // REQUIRES_NEW survives even when the caller later rolls back
    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public void recordRejection(long productId) {
        audit.record("reservation rejected for product " + productId);
    }
}

package com.example.catalog.product;

import java.util.List;
import java.util.Optional;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface ProductRepository extends JpaRepository<Product, Long> {

    // Derived query: where name = ?
    Optional<Product> findByName(String name);

    // Derived query: where lower(name) like lower(?)
    List<Product> findByNameContainingIgnoreCase(String term);

    boolean existsByNameAndPriceCents(String name, long priceCents);

    Page<Product> findByStockGreaterThan(int stock, Pageable pageable);

    // JPQL uses entity names and fields, not table and column names
    @Query("select p from Product p where p.priceCents between :min and :max order by p.priceCents")
    List<Product> findInPriceRange(@Param("min") long min, @Param("max") long max);

    // Native SQL is opt-in and uses the real schema names
    @Query(value = "select * from product where stock = 0", nativeQuery = true)
    List<Product> findOutOfStock();

    // Bulk update: it bypasses the persistence context, so callers are transactional
    @Modifying(clearAutomatically = true)
    @Query("update Product p set p.stock = p.stock - :quantity "
            + "where p.id = :id and p.stock >= :quantity")
    int decrementStock(@Param("id") long id, @Param("quantity") int quantity);
}

