// Only the web slice starts; the service is a mock bean
@WebMvcTest(ProductController.class)
class ProductControllerTest {

    @Autowired
    MockMvc mvc;

    @MockitoBean
    ProductService service;

    @Test
    @WithMockUser(roles = "USER")
    void listsProducts() throws Exception {
        given(service.list(0, 20))
                .willReturn(List.of(new ProductResponse(1L, "kettle", 8990L, 4)));

        mvc.perform(get("/api/products"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$[0].name").value("kettle"))
                .andExpect(jsonPath("$[0].priceCents").value(8990));
    }
}

