package com.example.catalog.config;

import org.springframework.boot.actuate.health.Health;
import org.springframework.boot.actuate.health.HealthIndicator;
import org.springframework.stereotype.Component;

@Component
public class InventoryHealthIndicator implements HealthIndicator {

    private final InventoryClient inventory;

    public InventoryHealthIndicator(InventoryClient inventory) {
        this.inventory = inventory;
    }

    // Appears as the "inventory" entry under /actuator/health
    @Override
    public Health health() {
        try {
            int pending = inventory.pendingShipments();
            return Health.up().withDetail("pendingShipments", pending).build();
        } catch (RuntimeException error) {
            return Health.down().withDetail("error", error.getMessage()).build();
        }
    }
}
